"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["44297"],{70084(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.oferta_curso.regime_de_funcionamento_invalido","status":422,"titulo":"Regime de funcionamento n\xe3o \xe9 um dos c\xf3digos aceitos"},"descricao":{"codigo":"uniplus.configuracao.oferta_curso.regime_de_funcionamento_invalido","requisitos":["UNI-REQ-0138"],"oQueAconteceu":["O `regimeDeFuncionamento` informado n\xe3o \xe9 `EXTENSIVO`, `INTENSIVO` nem\\n`ALTERNANCIA_PEDAGOGICA`. N\xe3o h\xe1 outros al\xe9m desses tr\xeas, e o valor \xe9 aceito por\\ncorrespond\xeancia textual exata com um desses tr\xeas c\xf3digos.","Tr\xeas enganos previs\xedveis levam a este erro:","- **Enviar um c\xf3digo do regime de turno.** `REGULAR` e `INTEGRAL` s\xe3o o\\n  vocabul\xe1rio da outra dimens\xe3o, que responde em *quantos turnos* a oferta\\n  funciona \u2014 n\xe3o em que regime ela funciona.\\n- **Enviar um c\xf3digo do formato pedag\xf3gico ou do programa de oferta.**\\n  `PRESENCIAL`, `SEMIPRESENCIAL` e `EAD` dizem **como** a aula acontece;\\n  `REGULAR`, `PARFOR`, `PRONERA`, `FORMA_PARA`, `PEPETI`, `CONVENIO_OUTRO` e\\n  `OUTRO` dizem a que programa a oferta se vincula. S\xe3o campos independentes,\\n  cada um com o seu.\\n- **Escrever a altern\xe2ncia com acento, espa\xe7o ou caixa diferente.** O c\xf3digo \xe9\\n  `ALTERNANCIA_PEDAGOGICA` \u2014 caixa alta, sem acento, com sublinhado.\\n  `Altern\xe2ncia Pedag\xf3gica`, `Alternancia Pedagogica` e\\n  `alternancia_pedagogica` s\xe3o recusados.","A compara\xe7\xe3o \xe9 exata: espa\xe7os nas pontas e diferen\xe7a entre mai\xfasculas e min\xfasculas\\nn\xe3o s\xe3o aceitos, nem valores num\xe9ricos."],"comoResolver":["Informe um dos tr\xeas c\xf3digos v\xe1lidos:","| Token | O que significa |\\n|---|---|\\n| `EXTENSIVO` | Modalidade regular: as atividades e disciplinas se distribuem de forma cont\xednua ao longo de um per\xedodo letivo regular, semestral. |\\n| `INTENSIVO` | Oferta concentrada: a carga hor\xe1ria de uma ou mais disciplinas \xe9 cumprida em tempo reduzido, geralmente em f\xe9rias letivas ou turmas especiais. |\\n| `ALTERNANCIA_PEDAGOGICA` | Altern\xe2ncia entre etapas presenciais na institui\xe7\xe3o (Tempo-Universidade) e etapas desenvolvidas na comunidade ou no meio profissional de origem (Tempo-Comunidade) \u2014 modelo padr\xe3o de cursos como a Licenciatura em Educa\xe7\xe3o do Campo. |","Se o campo n\xe3o foi informado de forma alguma, a causa \xe9 outra:\\n[regime de funcionamento obrigat\xf3rio](/erros/uniplus.configuracao.oferta_curso.regime_de_funcionamento_obrigatorio)."],"ondeAparece":["Cria\xe7\xe3o de uma oferta de curso","Atualiza\xe7\xe3o de uma oferta de curso"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Oferta curso"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);